require_once 'functions.php';require_login();$id=uid();$msg='';$err='';$s=$pdo->prepare('SELECT name,email,currency,created_at FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){$act=$_POST['action']??'';if($act==='profile'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$cur=$_POST['currency']??'INR';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($cur,['INR','USD','EUR','GBP','LKR'],true))$err='Check your name, email and currency.';else{try{$s=$pdo->prepare('UPDATE users SET name=?,email=?,currency=? WHERE id=?');$s->execute([$name,$email,$cur,$id]);$_SESSION['user_name']=$name;$_SESSION['user_email']=$email;$_SESSION['currency']=$cur;$msg='Profile settings saved.';$s=$pdo->prepare('SELECT name,email,currency,created_at FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch();}catch(PDOException $x){$err='That email may already be in use.';}}}elseif($act==='password'){$s=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$id]);$hash=$s->fetchColumn();$new=$_POST['new_password']??'';if(!password_verify($_POST['current_password']??'',$hash))$err='Current password is incorrect.';elseif(strlen($new)<8)$err='New password needs at least 8 characters.';else{$s=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$s->execute([password_hash($new,PASSWORD_DEFAULT),$id]);$msg='Password changed successfully.';}}}
start_page('Settings','settings.php');?>
